using System.Globalization;
using System.Text;

namespace XylemUI.Tools.CldrTableGen;

/// <summary>
/// Writes the generated files (design §4.11, "How the tables are made" and "Declaration and reference"): one class that derives from
/// <c>LocaleData</c> for each entry and for root, the plural rules as methods, the properties of <c>CldrLocales</c>, the list of
/// <c>CldrLocales.All</c>, the license of the data, and the samples of the plural rules for the tests. Every line ends with LF and
/// every file is UTF-8 without a byte order mark, whatever the OS, so that two runs write the same bytes.
/// </summary>
internal sealed class Output
{
    private const string CldrFolder = "src/XylemUI.Core/Localization/Cldr";
    private const string LicenseFile = "src/XylemUI.Core/LICENSE-CLDR.txt";
    private const string SamplesFile = "tests/XylemUI.Core.Tests/CldrPluralSamples.g.cs";

    private static readonly UTF8Encoding Utf8 = new(encoderShouldEmitUTF8Identifier: false);

    private readonly PinnedRelease _release;
    private readonly string _license;
    private readonly LocaleSet _locales;
    private readonly WeekData _week;
    private readonly PluralTables _plurals;

    /// <summary>
    /// Initializes a new instance of the <see cref="Output"/> class.
    /// </summary>
    /// <param name="release">The pinned release the data comes from.</param>
    /// <param name="license">The text of the zip's LICENSE.</param>
    /// <param name="locales">The set of locales.</param>
    /// <param name="week">The week data.</param>
    /// <param name="plurals">The plural rules.</param>
    public Output(PinnedRelease release, string license, LocaleSet locales, WeekData week, PluralTables plurals)
    {
        _release = release;
        _license = license;
        _locales = locales;
        _week = week;
        _plurals = plurals;
    }

    /// <summary>
    /// Returns a whole number as the invariant culture writes it.
    /// </summary>
    /// <param name="value">The number.</param>
    /// <returns>Its digits.</returns>
    public static string Number(int value) => value.ToString(CultureInfo.InvariantCulture);

    /// <summary>
    /// Writes every file under a root, at its path relative to the repository. The generated files of the CLDR folder that are there
    /// before are deleted first, so that a file the tool no longer writes does not stay.
    /// </summary>
    /// <param name="root">The repository, or the directory a test writes into.</param>
    public void Write(string root)
    {
        string folder = Path.Combine(root, CldrFolder);
        Directory.CreateDirectory(folder);
        foreach (string stale in Directory.GetFiles(folder, "*.g.cs"))
        {
            File.Delete(stale);
        }

        Save(Path.Combine(folder, "CldrLocales.g.cs"), Locales());
        Save(Path.Combine(folder, "CldrTables.g.cs"), Tables());
        Save(Path.Combine(folder, "CldrPluralRules.g.cs"), PluralRules());
        Save(Path.Combine(root, LicenseFile), _license);
        string samples = Path.Combine(root, SamplesFile);
        Directory.CreateDirectory(Path.GetDirectoryName(samples)!);
        Save(samples, Samples());
    }

    private static void Save(string path, string text) => File.WriteAllText(path, text.ReplaceLineEndings("\n"), Utf8);

    private static void Line(StringBuilder text, string line) => text.Append(line).Append('\n');

    private static string Literal(string value) =>
        "\"" + value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal) + "\"";

    private void Header(StringBuilder text)
    {
        string file = Path.GetFileName(new Uri(_release.Urls[0]).AbsolutePath);
        Line(text, "// <auto-generated>");
        Line(text, "// Generated by tools/CldrTableGen from " + file + ", CLDR " + _release.Version + " (vendor/versions.lock).");
        Line(text, "// SHA-256 of the zip: " + _release.Sha256 + ".");
        string counts =
            "// "
            + Number(_locales.Tables.Count)
            + " tables and root; "
            + Number(_locales.Entries.Count)
            + " entries of CldrLocales; plural rule sets: "
            + Number(_plurals.Cardinal.Count)
            + " cardinal, "
            + Number(_plurals.Ordinal.Count)
            + " ordinal, "
            + Number(_plurals.Pairs)
            + " pairs.";
        Line(text, counts);
        Line(text, "// Do not edit: run the tool again.");
        Line(text, "// </auto-generated>");

        // The data's license asks that its notice appear with every copy (design §9; the zip's LICENSE, also written to
        // src/XylemUI.Core/LICENSE-CLDR.txt).
        Line(text, "//");
        Line(text, "// The data is Unicode CLDR, under this notice:");
        Line(text, "//");
        foreach (string line in _license.TrimEnd('\n').Split('\n'))
        {
            Line(text, line.Length == 0 ? "//" : "// " + line);
        }

        Line(text, string.Empty);
    }

    private string Locales()
    {
        var text = new StringBuilder();
        Header(text);
        Line(text, "namespace XylemUI;");
        Line(text, string.Empty);
        Line(text, "public static partial class CldrLocales");
        Line(text, "{");
        bool first = true;
        foreach (LocaleEntry entry in _locales.Entries)
        {
            if (!first)
            {
                Line(text, string.Empty);
            }

            first = false;
            string summary =
                entry.DataTag == entry.Tag
                    ? "Gets the tables of <c>" + entry.Tag + "</c>."
                    : "Gets the tables of <c>"
                        + entry.DataTag
                        + "</c> under the tag <c>"
                        + entry.Tag
                        + "</c>, which CLDR reads as <c>"
                        + entry.DataTag
                        + "</c> (aliases.json).";
            Line(text, "    /// <summary>" + summary + "</summary>");
            Line(text, "    public static LocaleData " + entry.Identifier + " => Cldr" + entry.Identifier + ".Instance;");
        }

        Line(text, "}");
        return text.ToString();
    }

    private string Tables()
    {
        var text = new StringBuilder();
        Header(text);
        Line(text, "namespace XylemUI;");
        Line(text, string.Empty);
        Line(text, "/// <summary>");
        Line(text, "/// The release and the counts of the CLDR tables, which the tool counted (design §4.11, \"The set of locales\").");
        Line(text, "/// </summary>");
        Line(text, "internal static class CldrData");
        Line(text, "{");
        Constant(text, "string", "Version", Literal(_release.Version), "Gets the version of CLDR the tables come from.");
        Constant(text, "string", "Sha256", Literal(_release.Sha256), "Gets the SHA-256 of the json-full zip the tables come from.");
        Constant(text, "int", "TableCount", Number(_locales.Tables.Count), "Gets the number of locales with tables of their own, root left out.");
        Constant(text, "int", "EntryCount", Number(_locales.Entries.Count), "Gets the number of properties of CldrLocales, the alias entries in.");
        Constant(text, "int", "CardinalRuleSets", Number(_plurals.Cardinal.Count), "Gets the number of distinct sets of cardinal rules.");
        Constant(text, "int", "OrdinalRuleSets", Number(_plurals.Ordinal.Count), "Gets the number of distinct sets of ordinal rules.");
        Constant(
            text,
            "int",
            "PluralRuleSetPairs",
            Number(_plurals.Pairs),
            "Gets the number of distinct pairs of a cardinal and an ordinal set among the entries and root."
        );
        Line(text, "}");
        Line(text, string.Empty);
        Line(text, "/// <summary>");
        Line(text, "/// Lists every entry of <see cref=\"CldrLocales\"/>: referencing this class keeps every table in the binary.");
        Line(text, "/// </summary>");
        Line(text, "internal static class CldrAll");
        Line(text, "{");
        Line(text, "    /// <summary>");
        Line(text, "    /// The entries, in ordinal order of their tags.");
        Line(text, "    /// </summary>");
        Line(text, "    public static readonly IReadOnlyList<LocaleData> Locales =");
        Line(text, "    [");
        foreach (LocaleEntry entry in _locales.Entries)
        {
            Line(text, "        Cldr" + entry.Identifier + ".Instance,");
        }

        Line(text, "    ];");
        Line(text, "}");
        Class(text, _locales.Root, "The tables of root, which CLDR names und; its week is the world's (001).");
        foreach (LocaleEntry entry in _locales.Entries)
        {
            string summary =
                entry.DataTag == entry.Tag
                    ? "The tables of " + entry.Tag + "; its week is the one of the region " + entry.Region + "."
                    : "The tables of "
                        + entry.DataTag
                        + " under the tag "
                        + entry.Tag
                        + ", which cldr-core/supplemental/aliases.json reads as "
                        + entry.DataTag
                        + " (design §4.11, \"The set of locales\").";
            Class(text, entry, summary);
        }

        return text.ToString();
    }

    private static void Constant(StringBuilder text, string type, string name, string value, string summary)
    {
        Line(text, "    /// <summary>" + summary + "</summary>");
        Line(text, "    public const " + type + " " + name + " = " + value + ";");
    }

    private void Class(StringBuilder text, LocaleEntry entry, string summary)
    {
        Week week = _week.For(entry.Region);
        (PluralRuleSet cardinal, _, PluralRuleSet ordinal, _) = _plurals.ByTag[entry.DataTag];
        string locale = entry.Tag == "und" ? "default" : "Locale.Parse(" + Literal(entry.Tag) + ")";
        string name = "Cldr" + entry.Identifier;
        Line(text, string.Empty);
        Line(text, "/// <summary>");
        Line(text, "/// " + summary);
        Line(text, "/// </summary>");
        Line(text, "internal sealed class " + name + " : LocaleData");
        Line(text, "{");
        Line(text, "    /// <summary>");
        Line(text, "    /// The one instance, made when the class is first used.");
        Line(text, "    /// </summary>");
        Line(text, "    public static readonly " + name + " Instance = new();");
        Line(text, string.Empty);
        Line(text, "    private " + name + "()");
        string constructor =
            "        : base("
            + locale
            + ", DayOfWeek."
            + week.FirstDay
            + ", "
            + Number(week.MinimalDays)
            + ", DayOfWeek."
            + week.WeekendStart
            + ", DayOfWeek."
            + week.WeekendEnd
            + ") { }";
        Line(text, constructor);
        Line(text, string.Empty);
        Line(text, "    /// <inheritdoc/>");
        string rules = "CldrPluralRules." + cardinal.Method + ", CldrPluralRules." + ordinal.Method;
        Line(text, "    internal override PluralRules CreatePlurals() => new(" + rules + ");");
        Line(text, "}");
    }

    private string PluralRules()
    {
        var text = new StringBuilder();
        Header(text);
        Line(text, "namespace XylemUI;");
        Line(text, string.Empty);
        Line(text, "/// <summary>");
        Line(text, "/// The plural rules of CLDR as methods, one for each distinct set (design §4.11, \"Plural rules\"). A value that no rule");
        Line(text, "/// holds for is other.");
        Line(text, "/// </summary>");
        Line(text, "internal static class CldrPluralRules");
        Line(text, "{");
        bool first = true;
        foreach ((string kind, IReadOnlyList<PluralRuleSet> sets) in new[] { ("cardinal", _plurals.Cardinal), ("ordinal", _plurals.Ordinal) })
        {
            foreach (PluralRuleSet set in sets)
            {
                if (!first)
                {
                    Line(text, string.Empty);
                }

                first = false;
                Line(text, "    /// <summary>");
                Line(text, "    /// Selects the category with the " + kind + " rules of " + string.Join(", ", set.Keys) + ".");
                Line(text, "    /// </summary>");
                Line(text, "    /// <param name=\"operands\">The operands of the value.</param>");
                Line(text, "    /// <returns>The category.</returns>");
                if (set.Rules.Count == 0)
                {
                    Line(text, "    internal static PluralCategory " + set.Method + "(in PluralOperands operands) => PluralCategory.Other;");
                    continue;
                }

                Line(text, "    internal static PluralCategory " + set.Method + "(in PluralOperands operands)");
                Line(text, "    {");
                foreach (PluralRule rule in set.Rules)
                {
                    Line(text, "        // " + rule.Category + ": " + rule.Condition);
                    Line(text, "        if (" + rule.Expression + ")");
                    Line(text, "        {");
                    Line(text, "            return PluralCategory." + char.ToUpperInvariant(rule.Category[0]) + rule.Category[1..] + ";");
                    Line(text, "        }");
                    Line(text, string.Empty);
                }

                Line(text, "        return PluralCategory.Other;");
                Line(text, "    }");
            }
        }

        Line(text, "}");
        return text.ToString();
    }

    private string Samples()
    {
        var text = new StringBuilder();
        Header(text);
        Line(text, "namespace XylemUI.Tests;");
        Line(text, string.Empty);
        Line(text, "/// <summary>");
        Line(text, "/// The samples of CLDR's plural rules (the text after @integer and @decimal), which the tests select with every entry's");
        Line(text, "/// rules (design §4.11, \"Tests\").");
        Line(text, "/// </summary>");
        Line(text, "internal static class CldrPluralSamples");
        Line(text, "{");
        Line(text, "    /// <summary>");
        Line(text, "    /// Each entry's tag, root as und, and the keys of plurals.json and ordinals.json whose rules it takes.");
        Line(text, "    /// </summary>");
        Line(text, "    public static readonly (string Tag, string Cardinal, string Ordinal)[] Entries =");
        Line(text, "    [");
        foreach (LocaleEntry entry in _locales.Entries.Prepend(_locales.Root))
        {
            (_, string cardinalKey, _, string ordinalKey) = _plurals.ByTag[entry.DataTag];
            Line(text, "        (" + Literal(entry.Tag) + ", " + Literal(cardinalKey) + ", " + Literal(ordinalKey) + "),");
        }

        Line(text, "    ];");
        SampleList(text, "Cardinal", "plurals.json", _plurals.CardinalSamples);
        SampleList(text, "Ordinal", "ordinals.json", _plurals.OrdinalSamples);
        Line(text, "}");
        return text.ToString();
    }

    private static void SampleList(
        StringBuilder text,
        string name,
        string file,
        IReadOnlyDictionary<string, List<(string Category, string Samples)>> samples
    )
    {
        Line(text, string.Empty);
        Line(text, "    /// <summary>");
        Line(text, "    /// The samples of each category of each key of " + file + " that an entry takes.");
        Line(text, "    /// </summary>");
        Line(text, "    public static readonly (string Key, string Category, string Samples)[] " + name + " =");
        Line(text, "    [");
        foreach ((string key, List<(string Category, string Samples)> list) in samples)
        {
            foreach ((string category, string sample) in list)
            {
                Line(text, "        (" + Literal(key) + ", " + Literal(category) + ", " + Literal(sample) + "),");
            }
        }

        Line(text, "    ];");
    }
}
